t.script:
(function () {
    var tbody = document.getElementById('o_approval_product_lines');
    var addBtn = document.getElementById('o_add_approval_line');
    if (!tbody || !addBtn) return;

    // Bỏ dấu tiếng Việt + chữ thường để tìm không dấu
    function norm(s) {
        return (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
            .replace(/đ/g, 'd').replace(/Đ/g, 'D').toLowerCase();
    }

    var products = [];
    var src = document.getElementById('o_approval_product_source');
    if (src) {
        Array.prototype.forEach.call(src.options, function (o) {
            products.push({id: o.value, name: o.textContent, desc: o.dataset.desc || '', key: norm(o.textContent)});
        });
    }
    var MAX_RESULTS = 50;

    function bindRow(row) {
        var search = row.querySelector('.o_product_search');
        var hidden = row.querySelector('.o_product_id');
        var results = row.querySelector('.o_product_results');
        var descInput = row.querySelector('input[name="descriptions[]"]');

        function hideResults() {
            results.classList.add('d-none');
            results.innerHTML = '';
        }

        function choose(p) {
            hidden.value = p.id;
            search.value = p.name;
            search.classList.remove('is-invalid');
            search.classList.add('is-valid');
            if (descInput && !descInput.value) {
                descInput.value = p.desc || p.name;
            }
            hideResults();
            // Ẩn bàn phím điện thoại để thấy ô Số lượng
            search.blur();
        }

        function render() {
            var words = norm(search.value).split(/\s+/).filter(Boolean);
            results.innerHTML = '';
            var count = 0;
            for (var i = 0; i < products.length && count < MAX_RESULTS; i++) {
                var p = products[i];
                if (!words.every(function (w) { return p.key.indexOf(w) !== -1; })) continue;
                var item = document.createElement('button');
                item.type = 'button';
                item.className = 'list-group-item list-group-item-action py-2 small';
                item.textContent = p.name;
                item.addEventListener('click', choose.bind(null, p));
                results.appendChild(item);
                count++;
            }
            if (!count) {
                var empty = document.createElement('div');
                empty.className = 'list-group-item small text-muted';
                empty.textContent = 'Không tìm thấy sản phẩm';
                results.appendChild(empty);
            }
            results.classList.remove('d-none');
        }

        search.addEventListener('input', function () {
            // Gõ lại thì bỏ lựa chọn cũ, bắt buộc chọn lại từ danh sách
            hidden.value = '';
            search.classList.remove('is-valid');
            render();
        });
        search.addEventListener('focus', function () {
            if (!hidden.value) render();
            // Điện thoại: đợi bàn phím bật lên rồi cuộn ô tìm kiếm lên đầu để danh sách gợi ý không bị bàn phím che
            if (window.innerWidth < 768) {
                setTimeout(function () {
                    search.scrollIntoView({block: 'start', behavior: 'smooth'});
                }, 300);
            }
        });
        search.addEventListener('keydown', function (ev) {
            if (ev.key === 'Enter') {
                // Enter chọn kết quả đầu tiên thay vì submit form
                ev.preventDefault();
                var first = results.querySelector('button');
                if (first) first.click();
            } else if (ev.key === 'Escape') {
                hideResults();
            }
        });
        ['pointerdown', 'touchstart'].forEach(function (evName) {
            document.addEventListener(evName, function (ev) {
                if (!row.contains(ev.target)) hideResults();
            }, {passive: true});
        });
        var removeBtn = row.querySelector('.o_remove_line');
        if (removeBtn) {
            removeBtn.addEventListener('click', function () {
                if (tbody.querySelectorAll('.o_approval_product_row').length > 1) {
                    row.remove();
                }
            });
        }
    }

    bindRow(tbody.querySelector('.o_approval_product_row'));

    addBtn.addEventListener('click', function () {
        var template = tbody.querySelector('.o_approval_product_row').cloneNode(true);
        template.querySelector('.o_product_id').value = '';
        var s = template.querySelector('.o_product_search');
        s.value = '';
        s.classList.remove('is-valid', 'is-invalid');
        var r = template.querySelector('.o_product_results');
        r.innerHTML = '';
        r.classList.add('d-none');
        template.querySelector('input[name="descriptions[]"]').value = '';
        template.querySelector('input[name="quantities[]"]').value = '1';
        tbody.appendChild(template);
        bindRow(template);
        s.focus();
    });

    // Chặn gửi khi có dòng đã gõ nhưng chưa chọn sản phẩm từ danh sách, hoặc không có dòng nào
    var form = tbody.closest('form');
    if (form) {
        form.addEventListener('submit', function (ev) {
            var ok = true, hasLine = false;
            tbody.querySelectorAll('.o_approval_product_row').forEach(function (row) {
                var id = row.querySelector('.o_product_id').value;
                var s = row.querySelector('.o_product_search');
                if (id) { hasLine = true; return; }
                if (s.value.trim()) { ok = false; s.classList.add('is-invalid'); }
            });
            if (!ok || !hasLine) {
                ev.preventDefault();
                alert(!ok ? 'Vui lòng chọn sản phẩm từ danh sách gợi ý.' : 'Vui lòng chọn ít nhất 1 sản phẩm.');
            }
        });
    }
})();
